<form method="post" action="{{ $action }}">@csrf @php($marked=$roster->filter(fn ($row) => $records->has($row['student']->id))->count())<div class="attendance-toolbar"><p class="attendance-count" data-attendance-count data-total="{{ $roster->count() }}"><strong>{{ $marked }} de {{ $roster->count() }}</strong> marcados</p><button class="button button-secondary" type="button" data-mark-all-present>Todos SIM</button></div><div class="attendance-list">@forelse($roster as $index => $row)@php($student=$row['student'])@php($record=$records->get($student->id))<article class="card attendance-row"><div class="person-cell"><x-person-photo :person="$student->person" /><span><strong>{{ $student->person->social_name ?: $student->person->full_name }}</strong><small>{{ $student->registration_number }} · {{ $row['type']==='visitor' ? 'Visitante' : 'Matriculado' }}</small></span></div><input type="hidden" name="records[{{ $index }}][student_id]" value="{{ $student->id }}">@php($status=$record?->status)<fieldset class="yes-no" data-attendance-choice><legend class="sr-only">{{ $student->person->full_name }} veio à aula?</legend><input type="radio" id="yes-{{ $student->id }}" name="records[{{ $index }}][status]" value="present" @checked(in_array($status, ['present', 'makeup', 'trial'], true))><label class="yes-no-yes" for="yes-{{ $student->id }}">SIM</label><input type="radio" id="no-{{ $student->id }}" name="records[{{ $index }}][status]" value="absent" @checked(in_array($status, ['absent', 'excused_absence'], true))><label class="yes-no-no" for="no-{{ $student->id }}">NÃO</label></fieldset></article>@empty<div class="card empty-state"><p>Nenhum aluno nesta aula.</p></div>@endforelse</div>@if($roster->isNotEmpty())<div class="form-actions attendance-actions"><button class="button button-secondary" name="close_attendance" value="0">Salvar e continuar</button><button class="button button-primary" name="close_attendance" value="1">Finalizar chamada</button></div>@endif</form>
